// client/src/api/couponApi.js

import axiosInstance from './axiosInstance'; 
const COUPON_URL = '/coupons'; // 백엔드 라우트 경로를 '/api/coupons'로 가정

// 1. 사용자 쿠폰 목록 가져오기
export const getMyCoupons = async () => {
    try {
        const response = await axiosInstance.get(COUPON_URL);
        // 서버가 데이터만 배열로 응답한다고 가정합니다.
        return response.data;
    } catch (error) {
        throw error.response?.data?.message || '쿠폰 목록 조회 실패';
    }
};

// 2. 쿠폰 사용 처리 (redeemCoupon 함수 추가)
export const redeemCoupon = async (couponId) => {
    try {
        // 백엔드에 POST 요청을 보내 해당 쿠폰을 '사용됨' 상태로 변경 요청
        // 서버의 엔드포인트를 POST /coupons/:id/redeem 으로 가정합니다.
        const response = await axiosInstance.post(`${COUPON_URL}/${couponId}/redeem`);
        
        // 서버는 사용 처리된 쿠폰 객체를 응답으로 돌려준다고 가정합니다.
        return response.data; 
    } catch (error) {
        // 에러를 던져서 CouponCenter.jsx에서 catch하도록 합니다.
        throw error.response?.data || error.message; 
    }
};
// 🚨 이 파일을 저장하면 에러가 해결됩니다.
